    current = n

    while current != 1:
        collatz_sequence.append(current)
        if current % 2 == 0:
            current //= 2
        else:
            current = 3 * current + 1
    collatz_sequence.append(1)  # Include the last term, which is always 1

    odd_numbers = [num for num in collatz_sequence if num % 2 == 1]
    return sorted(odd_numbers)

